INSERT INTO `entity_templates` (`id`, `public_id`, `template_key`, `name`, `description`, `entity_type`, `default_categories_json`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, '01KYYHAB21Q866BVDH3K36BCE3', 'HO', 'Head Office', 'The registered head office. Usually holds the primary PF and ESIC registration.', 'HEAD_OFFICE', '[\"PF_QUERY\",\"ESI_QUERY\",\"PAYROLL\",\"HR_QUERY\",\"IT_SUPPORT\",\"GENERAL\"]', 1, 10, '2026-08-01 16:58:29.254', '2026-08-01 16:58:29.254'),
(2, '01KYYHAB289B1WQ3JVY4X1JGAR', 'MFG', 'Manufacturing Unit', 'A factory or plant. Normally registered for both PF and ESI.', 'PLANT', '[\"PF_QUERY\",\"ESI_QUERY\",\"PAYROLL\"]', 1, 20, '2026-08-01 16:58:29.256', '2026-08-01 16:58:29.256'),
(3, '01KYYHAB29G0DTKAZVBSFPA3JH', 'SVC', 'Services Division', 'A services or professional arm. Often PF-registered but above the ESI wage ceiling.', 'DIVISION', '[\"PF_QUERY\",\"PAYROLL\",\"HR_QUERY\"]', 1, 30, '2026-08-01 16:58:29.258', '2026-08-01 16:58:29.258'),
(4, '01KYYHAB2A0MJGMRA9WMB97KNN', 'LOG', 'Logistics & Warehousing', 'Warehouse and transport operations, typically ESI-heavy.', 'BRANCH', '[\"ESI_QUERY\",\"PAYROLL\"]', 1, 40, '2026-08-01 16:58:29.259', '2026-08-01 16:58:29.259'),
(5, '01KYYHAB2CPRHBZFTZQ91BKP91', 'CORP', 'Corporate Services', 'Shared corporate functions with no separate statutory registration.', 'DIVISION', '[\"HR_QUERY\",\"IT_SUPPORT\",\"GENERAL\"]', 1, 50, '2026-08-01 16:58:29.261', '2026-08-01 16:58:29.261');
INSERT INTO `faq_articles` (`id`, `public_id`, `tenant_id`, `section`, `question`, `answer`, `sort_order`, `is_active`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '01KZTMA2PGXNMZV9RFDYGXJT0T', 2, 'TICKETS', 'How do I raise a ticket?', 'Open <strong>Raise a ticket</strong> from the sidebar, choose the entity your query is about — PF Withdrawals, ESIC Card, and so on — and describe the problem. Attach any documents you already have; it usually saves a round trip.', 1, 1, NULL, '2026-08-12 09:19:30.512', '2026-08-12 09:19:30.512', NULL),
(2, '01KZTMA2PNQ57W1KHTK2X16S4K', 2, 'TICKETS', 'How long will my ticket take?', 'Every ticket carries an SLA based on its priority. You can see the due date on the ticket itself. Statutory queries that depend on a field office can take longer than the SLA, and the helpdesk will tell you when that happens rather than letting the clock run out silently.', 2, 1, NULL, '2026-08-12 09:19:30.518', '2026-08-12 09:19:30.518', NULL),
(3, '01KZTMA2PS58YP840XE7BJQDTH', 2, 'TICKETS', 'What do the ticket statuses mean?', '<strong>New</strong> — raised, not yet reviewed. <strong>Open</strong> — the helpdesk has accepted it. <strong>In progress</strong> — actively being worked. <strong>Awaiting you</strong> — we need something from you before we can continue. <strong>Awaiting helpdesk</strong> — the ball is with us. <strong>Resolved</strong> — done, and you can reopen it if it was not. <strong>Closed</strong> — settled.', 3, 1, NULL, '2026-08-12 09:19:30.522', '2026-08-12 09:19:30.522', NULL),
(4, '01KZTMA2PX8T1RNSK2F0XXRZS5', 2, 'TICKETS', 'Can I reopen a ticket after it is resolved?', 'Yes, within the reopen window your organisation has configured. Open the ticket and choose <strong>Reopen</strong>; it returns to the same team with its history intact.', 4, 1, NULL, '2026-08-12 09:19:30.526', '2026-08-12 09:19:30.526', NULL),
(5, '01KZTMA2Q10PTGA8MYPH1HWM49', 2, 'PF', 'My PF withdrawal has been pending for weeks. What now?', 'Raise a ticket under <strong>PF Withdrawals</strong> with your UAN and the claim ID from the EPFO portal. The helpdesk follows it up with the field office and records each response on the ticket.', 1, 1, NULL, '2026-08-12 09:19:30.530', '2026-08-12 09:19:30.530', NULL),
(6, '01KZTMA2Q64NW610GESPG2NG4K', 2, 'PF', 'Why does my passbook show no recent contributions?', 'Passbook entries appear only after the employer\'s ECR is filed and reconciled, which usually lags by a few weeks. If more than two months are missing, raise it under <strong>Employer Contributions</strong>.', 2, 1, NULL, '2026-08-12 09:19:30.534', '2026-08-12 09:19:30.534', NULL),
(7, '01KZTMA2Q9NQFMRV0RBV47F30D', 2, 'PF', 'How do I correct my name or date of birth?', 'Raise a ticket under <strong>Correction Requests</strong> and attach the supporting document — Aadhaar or PAN for a name, and a birth certificate or school record for a date of birth. Corrections are a joint request between you and the employer.', 3, 1, NULL, '2026-08-12 09:19:30.538', '2026-08-12 09:19:30.538', NULL),
(8, '01KZTMA2QD1X5XP9W9NZC6N0AX', 2, 'PF', 'What is the difference between a transfer and a withdrawal?', 'A <strong>transfer</strong> moves your accumulated balance from a previous employer into your current account and keeps the service continuous. A <strong>withdrawal</strong> takes the money out and breaks that continuity, which affects pension eligibility.', 4, 1, NULL, '2026-08-12 09:19:30.542', '2026-08-12 09:19:30.542', NULL),
(9, '01KZTMA2QJMBADD6542P5MF5QY', 2, 'ESIC', 'I have not received my ESIC card.', 'Raise a ticket under <strong>ESIC Card</strong> with your insurance number. If registration was completed but no card issued, the helpdesk chases it with the branch office.', 1, 1, NULL, '2026-08-12 09:19:30.547', '2026-08-12 09:19:30.547', NULL),
(10, '01KZTMA2QP5W6QHVG09DWB5Y5D', 2, 'ESIC', 'My dispensary is in the wrong city.', 'Raise it under <strong>ESIC Dispensary</strong> with your current address. A dispensary change needs the employer\'s endorsement, which the helpdesk arranges.', 2, 1, NULL, '2026-08-12 09:19:30.551', '2026-08-12 09:19:30.551', NULL),
(11, '01KZTMA2QVHXP3DPRR067ZAK2K', 2, 'ACCOUNT', 'I cannot sign in.', 'Use <strong>Forgot password</strong> on the sign-in screen. Employees can also sign in with an employee code, mobile number, UAN or PAN instead of an email address. If the account is locked after repeated failures, it unlocks automatically, or your administrator can unlock it.', 1, 1, NULL, '2026-08-12 09:19:30.555', '2026-08-12 09:19:30.555', NULL),
(12, '01KZTMA2QYSK0ASJKZ2GQPPGFY', 2, 'ACCOUNT', 'How do I change what I am notified about?', 'Open <strong>Preferences → Notifications</strong>. Each event can be switched on or off per channel. Channels your organisation has not enabled are shown greyed out rather than hidden, so you can see what exists.', 2, 1, NULL, '2026-08-12 09:19:30.559', '2026-08-12 09:19:30.559', NULL),
(13, '01KZTMA2R2CQX66F58PBCCSH2K', 2, 'ACCOUNT', 'Who can see my tickets?', 'You, the helpdesk staff working them, and the administrators of your organisation whose remit covers your establishment. Other employees cannot see your tickets.', 3, 1, NULL, '2026-08-12 09:19:30.563', '2026-08-12 09:19:30.563', NULL),
(170, '01KZXA3VH0DDR30Z1WH7DVDR8C', 2, 'PARTNERS', 'Can I raise a ticket for one of my employees?', 'Yes. Choose <strong>Raise a ticket</strong> and search for the employee in the <strong>Raised for</strong> field. The ticket is recorded against them, flagged as raised on your behalf, and they can follow it themselves.', 1, 1, NULL, '2026-08-13 10:19:04.097', '2026-08-13 10:19:04.097', NULL),
(171, '01KZXA3VH55689SS7PNK15T2EX', 2, 'PARTNERS', 'Why can I see my employees but not edit them?', 'The employee master is maintained by the helpdesk, so that statutory identifiers stay consistent with what has been filed. You can see everything, including UAN, PF and ESIC numbers. To change something, raise a ticket under <strong>Correction Requests</strong> and it is amended at source.', 2, 1, NULL, '2026-08-13 10:19:04.101', '2026-08-13 10:19:04.101', NULL),
(172, '01KZXA3VH8H5K86P5YQ2EXTBGS', 2, 'PARTNERS', 'Which employees and entities can I see?', 'Whatever your account has been allocated. A client administrator sees the whole organisation; an executive sees only the entities allocated to them. If something you expect is missing, it is an allocation to be widened rather than a fault — ask the helpdesk.', 3, 1, NULL, '2026-08-13 10:19:04.105', '2026-08-13 10:19:04.105', NULL),
(173, '01KZXA3VHCSW535V4R9N7J8Q24', 2, 'PARTNERS', 'Can I see the helpdesk\'s internal notes?', 'No. Notes marked internal are between the helpdesk staff working the ticket. Everything addressed to you or your employee appears in the conversation.', 4, 1, NULL, '2026-08-13 10:19:04.108', '2026-08-13 10:19:04.108', NULL),
(174, '01KZXA3VHFTCD5B2A11NGFAB3X', 2, 'PARTNERS', 'How do I get a list of my organisation\'s tickets?', 'Open <strong>Reports</strong>, choose the report and the period, and download it as CSV, Excel or PDF. The ticket list itself also exports whatever you have filtered it to.', 5, 1, NULL, '2026-08-13 10:19:04.112', '2026-08-13 10:19:04.112', NULL),
(175, '01KZXA3VHKA1BGPGZSXR09HABY', 2, 'PARTNERS', 'Can I switch an entity off?', 'No — switching an establishment off hides its tickets from everybody, so it is a helpdesk action. Ask the helpdesk and it is done with the effect explained first.', 6, 1, NULL, '2026-08-13 10:19:04.116', '2026-08-13 10:19:04.116', NULL),
(242, '01KZXA3WGB097FQSN2QQHAV1VY', 1, 'DESK', 'Why can I not assign a ticket to a particular agent?', 'An agent works the clients their remit covers. An agent with no clients assigned covers every client; an agent with clients assigned covers exactly those. The assign menu offers only the agents whose remit covers that ticket\'s client — widen it under <strong>Clients → Agents covering this client</strong>.', 1, 1, NULL, '2026-08-13 10:19:05.100', '2026-08-13 10:19:05.100', NULL),
(243, '01KZXA3WGDWQ8D3EPG3AX4AK6Z', 1, 'DESK', 'What is the difference between assigning and transferring?', '<strong>Assign</strong> gives the ticket to a person. <strong>Transfer</strong> moves it to a department, for when the query belongs to another statutory line rather than another individual. <strong>Escalate</strong> raises it without changing who holds it.', 2, 1, NULL, '2026-08-13 10:19:05.102', '2026-08-13 10:19:05.102', NULL),
(244, '01KZXA3WGGMC1EAPAWKAQNDRA8', 1, 'DESK', 'When should a note be internal?', 'Whenever it is not addressed to the requester: what you found on the EPFO portal, what you suspect, what you are waiting on. Internal notes are visible to admins and agents only — never to the client\'s partners or to the employee.', 3, 1, NULL, '2026-08-13 10:19:05.105', '2026-08-13 10:19:05.105', NULL),
(245, '01KZXA3WGKSFXPZ623T0PQ0VS8', 1, 'DESK', 'The employee\'s statutory details look wrong. Where do I correct them?', 'On the person\'s record under <strong>Users</strong>. The ticket rail shows the same identifiers so you can check them without leaving the ticket, but the record is the source.', 4, 1, NULL, '2026-08-13 10:19:05.107', '2026-08-13 10:19:05.107', NULL),
(246, '01KZXA3WGPCJPZ0H2TV629TVBH', 1, 'DESK', 'What stops the SLA clock?', 'Only <strong>Awaiting employee</strong>. Waiting on the helpdesk is exactly what an SLA measures, so <strong>Awaiting helpdesk</strong> keeps the clock running.', 5, 1, NULL, '2026-08-13 10:19:05.110', '2026-08-13 10:19:05.110', NULL),
(247, '01KZXA3WGRSFW9GWNWY24D6SXK', 1, 'CLIENTS', 'How do I add a client?', '<strong>Clients → Add client</strong>. The name fills in the workspace address, which becomes part of the portal URL and cannot be changed afterwards. Everything else can.', 1, 1, NULL, '2026-08-13 10:19:05.112', '2026-08-13 10:19:05.112', NULL),
(248, '01KZXA3WGTHEVXE3JE10E42K73', 1, 'CLIENTS', 'What happens when I delete a client?', 'It is taken offline and archived — everyone signed in loses access immediately, and its tickets stop appearing. Nothing is erased, and an administrator can restore it. The confirmation says so before you commit.', 2, 1, NULL, '2026-08-13 10:19:05.114', '2026-08-13 10:19:05.114', NULL),
(249, '01KZXA3WGW465A7Q13X80M6RTE', 1, 'CLIENTS', 'Who decides which agent covers which client?', 'An administrator, under <strong>Clients → Agents covering this client</strong>. Leaving a client with no agents assigned means every agent covers it.', 3, 1, NULL, '2026-08-13 10:19:05.116', '2026-08-13 10:19:05.116', NULL),
(250, '01KZXA3WGZEVFGGGSSM76NZBRK', 1, 'USERS', 'What password does a new user get?', 'Their PAN and year of birth, lowercase — <code>abcde1234f@1990</code>. It is shown once when the account is created, with a copy button, and they must change it when they first sign in.', 1, 1, NULL, '2026-08-13 10:19:05.119', '2026-08-13 10:19:05.119', NULL),
(251, '01KZXA3WH2W1663SJG600BZM7Z', 1, 'USERS', 'Can two people share a PAN?', 'Two employees of the same client cannot — that is a data entry error which would merge two people\'s statutory records. An agent or a partner may share a PAN with an employee, because one person legitimately holds more than one account.', 2, 1, NULL, '2026-08-13 10:19:05.122', '2026-08-13 10:19:05.122', NULL),
(252, '01KZXA3WH4H1X0FBFA2GN8F4DZ', 1, 'USERS', 'What is the difference between an agent, a partner and an employee?', 'An <strong>agent</strong> is ComplyDesk staff and works across clients. A <strong>partner</strong> administers one client and sees its people and tickets without editing them. An <strong>employee</strong> raises and follows their own queries.', 3, 1, NULL, '2026-08-13 10:19:05.125', '2026-08-13 10:19:05.125', NULL),
(253, '01KZXA3WH75KBDYA5FE1RJYF6K', 1, 'REPORTS', 'Why does a report show fewer tickets than I expect?', 'Every report is scoped to what you can see. An agent\'s report covers the clients they are assigned to; a partner\'s covers their own client. Check the client selector before comparing two numbers.', 1, 1, NULL, '2026-08-13 10:19:05.127', '2026-08-13 10:19:05.127', NULL);
