(5, '01M0AHXZTE6J5CQJ068PS83X08', 2, 2, 50, 'Cannot export the SLA report', 'BUG', 'The export button returns an error when a date range is applied.', 'OPEN', 'NORMAL', NULL, NULL, NULL, '2026-08-18 13:45:48.110', '2026-08-18 13:45:48.110', NULL),
(6, '01M0AHY09MNNABTVYFRW5PNDP7', 2, 2, 93, 'How do I download my payslip', 'QUESTION', 'I cannot find the payslip section.', 'OPEN', 'NORMAL', NULL, NULL, NULL, '2026-08-18 13:45:48.597', '2026-08-18 13:45:48.597', NULL),
(7, '01M0AK4RT2K4M36XTGEGV1T36A', 2, 2, 50, 'Final sweep help request', 'QUESTION', 'Checking the workflow end to end.', 'OPEN', 'NORMAL', NULL, NULL, NULL, '2026-08-18 14:06:58.883', '2026-08-18 14:06:58.883', NULL);
