INSERT INTO `roles` (`id`, `public_id`, `tenant_id`, `role_key`, `alias_of`, `name`, `description`, `portal`, `is_system`, `is_deprecated`, `created_at`, `updated_at`) VALUES
(1, '01KYYHAANT38KV6TCEQZG6C1QV', NULL, 'SUPER_ADMIN', NULL, 'Super Admin', 'Complete system access. Manages clients, sites, users, categories, SLAs, global reports, dashboards and system notifications.', 'admin', 1, 0, '2026-08-01 16:58:28.860', '2026-08-18 13:51:23.223'),
(2, '01KYYHAARDMPGCQJ3ZE0TTGNAS', NULL, 'HELPDESK_MASTER_ADMIN', 'SUPER_ADMIN', 'Helpdesk Master Administrator', 'Complete access within a client workspace.', 'admin', 1, 1, '2026-08-01 16:58:28.942', '2026-08-05 15:19:51.571'),
(3, '01KYYHAATXBMGXGD4NX3FEFYZF', NULL, 'HELPDESK_ADMIN', 'HELPDESK_HEAD', 'Helpdesk Administrator', 'Runs the helpdesk: assigns work, configures categories and SLAs, sees every ticket.', 'agents', 1, 1, '2026-08-01 16:58:29.022', '2026-08-05 15:19:51.574'),
(4, '01KYYHAAX1REJ2HSPBW5FFV1CZ', NULL, 'HELPDESK_EXECUTIVE', NULL, 'Helpdesk Executive', 'Works tickets across every client: responds, requests information, uploads documents, updates status, adds internal notes and transfers. Does not administer clients or delete users.', 'agents', 1, 0, '2026-08-01 16:58:29.091', '2026-08-18 13:51:23.326'),
(5, '01KYYHAAY1KB50SS680XXWQW9W', NULL, 'CLIENT_MASTER_ADMIN', 'CLIENT_ADMIN', 'Client Master Administrator', 'Oversees every entity belonging to the client. May correct client and organisation details, but never add or remove a client.', 'partner', 1, 1, '2026-08-01 16:58:29.122', '2026-08-05 15:19:51.577'),
(6, '01KYYHAAYMQCR43A83C46KP64W', NULL, 'ENTITY_ADMIN', 'CLIENT_EXECUTIVE', 'Entity Administrator', 'Sees tickets and users for the entities and sites assigned to them.', 'partner', 1, 1, '2026-08-01 16:58:29.141', '2026-08-05 15:19:51.580'),
(7, '01KYYHAAZ6PVDTG46SHEBQKDJM', NULL, 'DEPARTMENT_ADMIN', 'CLIENT_EXECUTIVE', 'Department Administrator', 'Handles tickets pending on their department and supplies departmental input.', 'partner', 1, 1, '2026-08-01 16:58:29.159', '2026-08-05 15:19:51.580'),
(8, '01KYYHAAZW2BZPN4N0F6MVJX1T', NULL, 'EMPLOYEE', NULL, 'Employee', 'End user. Raises and tracks their own tickets, attaches and downloads files, replies, and reopens their own resolved tickets within the window.', 'user', 1, 0, '2026-08-01 16:58:29.182', '2026-08-18 13:51:23.386'),
(9, '01KYYHAB330E3ZMPDHVMNFQTAB', NULL, 'KARMA_SUPER_ADMIN', 'SUPER_ADMIN', 'Karma Super Admin', 'Unrestricted control across every client. Onboards clients, manages modules and feature flags, and administers agents, partners and employees.', 'admin', 1, 1, '2026-08-01 16:58:29.284', '2026-08-05 15:19:51.571'),
(10, '01KYYHAB4WYQVBQDJ2661XYNW5', NULL, 'KARMA_AGENT', 'HELPDESK_HEAD', 'Karma Agent', 'Internal support staff. Works only on the clients assigned to them: onboards those clients, manages their users and tickets, and reports on them.', 'agents', 1, 1, '2026-08-01 16:58:29.341', '2026-08-05 15:19:51.574'),
(11, '01KYYHAB6DS8F30V08J8JKRAX3', NULL, 'PARTNER', 'CLIENT_ADMIN', 'Partner', 'Client-side administrator — the client\'s own admin or HR. Raises tickets on behalf of employees, sees every ticket in their organisation, manages their employees, and maintains the organisation profile.', 'partner', 1, 1, '2026-08-01 16:58:29.390', '2026-08-05 15:19:51.577'),
(12, '01KYYHAB76FFQVGFVX1JAMG2S1', NULL, 'PARTNER_EXECUTIVE', 'CLIENT_EXECUTIVE', 'Partner Executive', 'Delegated user under a Partner. Works within the entities, sites and departments assigned to them, and inherits nothing beyond that scope.', 'partner', 1, 1, '2026-08-01 16:58:29.415', '2026-08-05 15:19:51.580'),
(13, '01799091B28DB111F1A3372800', NULL, 'AGENT', 'HELPDESK_HEAD', 'Agent', 'ComplyDesk support staff. Resolves tickets for every client, and creates and administers clients, their organisation structure and their users.', 'agents', 1, 1, '2026-08-01 19:30:25.515', '2026-08-05 15:19:51.574'),
(14, '01977528B3900311F1A3372800', NULL, 'HELPDESK_HEAD', NULL, 'Helpdesk Head', 'Runs the desk across every client. Everything an executive can do, plus assigning and transferring work, escalating, closing, and operational reporting. Also creates and administers clients.', 'agents', 1, 0, '2026-08-04 18:22:48.621', '2026-08-05 15:19:51.559'),
(15, '0197752D89900311F1A3372800', NULL, 'CLIENT_ADMIN', NULL, 'Client Admin', 'Client-side administrator. Sees every entity and location allocated to them: dashboards, ticket search, SLA monitoring and report downloads. Cannot reply to tickets unless that permission is explicitly granted.', 'partner', 1, 0, '2026-08-04 18:22:48.621', '2026-08-05 15:19:51.559'),
(16, '0197752E3E900311F1A3372800', NULL, 'CLIENT_EXECUTIVE', NULL, 'Client Executive', 'Client-side user segmented to their own entity or location. Raises tickets on behalf of the employees there and tracks them. Cannot edit responses or reach another entity\'s data.', 'partner', 1, 0, '2026-08-04 18:22:48.621', '2026-08-05 15:19:51.559');
